/**
 * Curated font registry — a broad set of the strongest, ATS-safe resume
 * typefaces. All families are SELF-HOSTED: the woff2
 * files live in public/fonts/ and their @font-face rules are in
 * src/styles/fonts.css (generated by scripts/fetch-fonts.cjs). The app makes
 * ZERO external font requests — nothing is fetched from Google. Because the live
 * preview and the native print render in the SAME browser, the printed PDF is
 * byte-identical to the preview.
 */
import { ARABIC_SCRIPT_CLASS } from '@/lib/rtlBlocks'

export type FontCategory = 'sans' | 'serif' | 'mono' | 'display' | 'handwriting'

export interface FontDef {
  /** Display + CSS family name */
  name: string
  /** What the font menus call it, when the name alone does not say what it
   *  is for. The CSS family is still `name`. */
  label?: string
  category: FontCategory
  /** Google Fonts family query (defaults to name) */
  family?: string
  /** Weights to request */
  weights?: number[]
  /** Italic axis available */
  italic?: boolean
  /** CSS fallback stack */
  fallback?: string
  /** Bundled families that draw what this one lacks, tried BEFORE the
   *  category's script chain: a small display face falls back to the text
   *  face it was drawn to sit beside, not to whatever the category offers. */
  chain?: string[]
  /** The face does not draw all of Basic Latin (an @ or a $ is missing), so
   *  the PDF painter checks every run set in it rather than only the runs
   *  outside Latin (src/lib/pdf/textFallback.ts, mayNeedFallback). */
  partialLatin?: true
}

