const FALLBACKS: Record<FontCategory, string> = {
  sans: 'ui-sans-serif, system-ui, -apple-system, sans-serif',
  serif: 'ui-serif, Georgia, Cambria, "Times New Roman", serif',
  mono: 'ui-monospace, SFMono-Regular, Menlo, monospace',
  display: 'ui-sans-serif, system-ui, sans-serif',
  handwriting: 'cursive',
}

export const FONT_MAP: Record<string, FontDef> = Object.fromEntries(FONTS.map((f) => [f.name, f]))

/**
 * Bundled families that draw the scripts a Latin-only family cannot, one
 * chain per category: the category's own face first (a serif resume keeps a
 * serif Cyrillic), then Inter, which covers Cyrillic, Greek and Vietnamese
 * in full. These sit in the CSS stack right after the chosen family, so the
 * browser draws a Cyrillic letter with them instead of with whatever system
 * font it finds; the PDF painter walks the same chain (src/lib/pdf/
 * textFallback.ts), so the page and the export agree glyph for glyph.
 */
export const SCRIPT_FALLBACKS: Record<FontCategory, string[]> = {
  sans: ['Inter'],
  serif: ['Source Serif 4', 'Inter'],
  mono: ['Source Code Pro', 'Inter'],
  display: ['Oswald', 'Inter'],
  handwriting: ['Inter'],
}

/**
 * The bundled MARKS family — four bullet glyphs (◦ U+25E6, ▪ U+25AA, ✓ U+2713,
 * ◆ U+25C6) that NO bundled family carries: measured across all 158 PDF faces
 * and all 257 web-font subset files, 0 of each. Generated outright by
 * scripts/make-marks-font.py, so its licence is this repository's own.
 *
 * It is deliberately NOT in `FONTS` — nobody should be able to set a resume in
 * it — and NOT in `SCRIPT_FALLBACKS`, which is about scripts and whose members
 * must draw Cyrillic, Greek and Vietnamese. It is appended to every chain
 * below instead, so it is the LAST thing tried: the bullet, en dash and angle
 * quote every family already has keep coming from the resume's own face, and
 * only the four marks nothing has fall through to this.
 *
 * Both sides read the chain: the browser through `fontStack` (the CSS the
 * canvas draws with) and the painter through `PdfFontCache.coverage`. Before
 * it existed, a ✓ or ◆ bullet was drawn on the canvas from whatever system
 * font the reader happened to have, and dropped from the PDF entirely.
 */
export const MARKS_FAMILY = 'CVAurum Marks'

/**
 * The family that draws Arabic script - Persian, Arabic, Urdu, Pashto. NO other
 * bundled face carries a single one of those letters, so the browser used to
 * pick whatever Arabic face the reader's computer happened to have. It is
 * appended to every chain, after the Latin-adjacent script fallbacks (those
 * must draw Cyrillic, Greek and Vietnamese, which this face cannot) and BEFORE
 * the marks family, so a Persian bullet no face has still lands on the marks.
 *
 * It sits behind the chosen face, so only a character the chosen face does not
 * have ever reaches it - and in the CSS stack it is named by its fallback alias
 * (ARABIC_FALLBACK_FAMILY), so what reaches it is Arabic script and nothing
 * else.
 */
export const ARABIC_FAMILY = 'Vazirmatn'

/**
 * The name the Arabic face goes by as a FALLBACK in the CSS stack: the same
 * woff2 files, declared with the arabic subset alone (src/styles/
 * fonts-arabic-fallback.css). Under its own name Vazirmatn also ships latin
 * and latin-ext files, so an arrow, a minus sign or an accented letter the
 * chosen face lacked could come out in Vazirmatn on a resume with no Arabic
 * at all. The PDF side reads the alias as ARABIC_FAMILY (fontIndex.ts), and
 * walks it only for a run with Arabic letters (pdf/fonts.ts `coverage`).
 */
export const ARABIC_FALLBACK_FAMILY = 'Vazirmatn Arabic'

const ARABIC_SCRIPT = new RegExp(`[${ARABIC_SCRIPT_CLASS}]`)

/** Does this text contain a letter of the Arabic script? Those are exactly the
 *  characters only the Arabic family can draw, so they decide whether an export
 *  has to wait for that face - and whether the browser has to shape the page
 *  instead of the native painter (src/lib/pdf/export.ts).
 *
 *  The presentation forms stop at U+FEFC: U+FEFF in that block is the
 *  byte-order mark, which a pasted or imported line can start with and which
 *  is no letter of any script. */
export function usesArabicScript(text: string): boolean {
  return ARABIC_SCRIPT.test(text)
}

/** The fallback families for `name`, in order, never naming `name` itself. */
export function scriptFallbacks(name?: string): string[] {
  const def = name ? FONT_MAP[name] : undefined
  const chain = [
    ...(def?.chain ?? []),
    ...SCRIPT_FALLBACKS[def?.category ?? 'sans'],
    ARABIC_FAMILY,
    MARKS_FAMILY,
  ]
  return [...new Set(chain)].filter((f) => f !== name)
}

export function fontStack(name?: string): string {
  if (!name) return FALLBACKS.sans
  const def = FONT_MAP[name]
  const fb = def ? def.fallback ?? FALLBACKS[def.category] : FALLBACKS.sans
  // The Arabic face as a fallback is the arabic-only alias; chosen, it keeps
  // its real name (and every subset) at the head of the stack.
  const chain = scriptFallbacks(name).map((f) => `"${f === ARABIC_FAMILY ? ARABIC_FALLBACK_FAMILY : f}"`)
  return [`"${name}"`, ...chain, fb].join(', ')
}

/**
 * No-op kept for API compatibility. Fonts are self-hosted and their @font-face
 * rules ship in the bundle (src/styles/fonts.css), so there is nothing to inject
 * — the browser lazily fetches the (same-origin, service-worker-precached) woff2
 * on first use. Safe to call on every render.
 */
export function ensureFont(_name?: string): void {
  /* fonts are bundled and always available — nothing to do */
}

/**
 * Resolve only once the requested faces are actually rasterizable. The @font-face
 * rules are already registered (bundled CSS), so we just drive `document.fonts.load`
 * for the specific faces and await `fonts.ready`. This guarantees the print/PDF
 * never falls back to a system font.
 */
export async function ensureFontsReady(names: (string | undefined)[]): Promise<void> {
  const real = names.filter((n): n is string => !!n)
  if (typeof document === 'undefined' || !('fonts' in document)) return
  const fonts = (document as Document & { fonts: FontFaceSet }).fonts
  // The Arabic face is drawn as a fallback under its alias, whose files cover
  // Arabic script alone: a load with no text asks for a space, which matches
  // none of them, so both names are loaded for an Arabic letter.
  const loads = (n: string) =>
    n === ARABIC_FAMILY
      ? [ARABIC_FAMILY, ARABIC_FALLBACK_FAMILY].flatMap((f) => [
          fonts.load(`400 1em "${f}"`, 'ا'),
          fonts.load(`700 1em "${f}"`, 'ا'),
        ])
      : [fonts.load(`400 1em "${n}"`), fonts.load(`700 1em "${n}"`)]
  try {
    await Promise.all(real.flatMap(loads).map((p) => p.catch(() => undefined)))
    await fonts.ready
  } catch {
    /* ignore */
  }
}

export const FONTS_BY_CATEGORY: Record<FontCategory, FontDef[]> = {
  sans: FONTS.filter((f) => f.category === 'sans'),
  serif: FONTS.filter((f) => f.category === 'serif'),
  mono: FONTS.filter((f) => f.category === 'mono'),
  display: FONTS.filter((f) => f.category === 'display'),
  handwriting: FONTS.filter((f) => f.category === 'handwriting'),
}
